// Gemini ka JSON parse karke har scene ko alag item banao
const raw = $input.first().json.candidates[0].content.parts[0].text;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
const parsed = JSON.parse(cleaned);

if (!Array.isArray(parsed.scenes) || parsed.scenes.length === 0) {
  throw new Error('Gemini ne scenes nahi diye — workflow dobara run karo');
}

const meta = {
  title: parsed.title,
  description: parsed.description,
  tags: parsed.tags,
};

return parsed.scenes.map((s, i) => ({
  json: {
    scene_index: i + 1,
    hook: s.hook,
    voiceover: s.voiceover,
    captions: Array.isArray(s.captions) ? s.captions : [],
    veo_prompt: s.veo_prompt,
    outro_prompt: parsed.outro_prompt,
    meta,
  },
}));

// Gemini TTS ka raw PCM (base64) -> WAV file (24kHz mono 16-bit)
const scenes = $('Split Scenes').all();

function wavFromBase64(b64) {
  const pcm = Buffer.from(b64, 'base64');
  const sampleRate = 24000, bitsPerSample = 16, channels = 1;
  const byteRate = (sampleRate * channels * bitsPerSample) / 8;
  const blockAlign = (channels * bitsPerSample) / 8;
  const header = Buffer.alloc(44);
  header.write('RIFF', 0);
  header.writeUInt32LE(36 + pcm.length, 4);
  header.write('WAVE', 8);
  header.write('fmt ', 12);
  header.writeUInt32LE(16, 16);
  header.writeUInt16LE(1, 20);
  header.writeUInt16LE(channels, 22);
  header.writeUInt32LE(sampleRate, 24);
  header.writeUInt32LE(byteRate, 28);
  header.writeUInt16LE(blockAlign, 32);
  header.writeUInt16LE(bitsPerSample, 34);
  header.write('data', 36);
  header.writeUInt32LE(pcm.length, 40);
  return Buffer.concat([header, pcm]).toString('base64');
}

return $input.all().map((item, i) => {
  const parts = item.json.candidates[0].content.parts;
  const audioPart = parts.find((p) => p.inlineData) || parts[0];
  const s = scenes[i].json;
  return {
    json: {
      scene_index: s.scene_index,
      hook: s.hook,
      voiceover: s.voiceover,
      captions: s.captions,
      veo_prompt: s.veo_prompt,
    },
    binary: {
      data: {
        data: wavFromBase64(audioPart.inlineData.data),
        mimeType: 'audio/wav',
        fileName: 'scene-' + s.scene_index + '-voiceover.wav',
      },
    },
  };
});

// Saare Veo operations check karo — sab done hone tak pending batao
const ops = $input.all();

const failed = ops.find((o) => o.json.error);
if (failed) {
  const msg = (failed.json.error && failed.json.error.message) || JSON.stringify(failed.json.error);
  throw new Error('Veo render fail hua: ' + msg);
}

const pending = ops.filter((o) => !o.json.done).length;
if (pending > 0) {
  return [{ json: { all_done: false, pending } }];
}

const scenes = $('Split Scenes').all().map((s, i) => {
  const resp = ops[i].json.response || {};
  const gvr = resp.generateVideoResponse || {};
  const samples = gvr.generatedSamples || [];
  return {
    scene_index: s.json.scene_index,
    hook: s.json.hook,
    captions: s.json.captions,
    voiceover: s.json.voiceover,
    video_uri: samples[0] && samples[0].video ? samples[0].video.uri : null,
  };
});

if (scenes.some((s) => !s.video_uri)) {
  throw new Error('Veo ne video URI nahi diya (safety filter block ho sakta hai) — topic/prompt thoda change karke try karo');
}

return [{ json: { all_done: true, scenes } }];

// Scene data + hosted URLs ek jagah collect karo
const scenes = $('Veo Collector').first().json.scenes;
const clips = $('7. Host Veo Clip (tmpfiles.org)').all();
const voiceovers = $('4. Host Voiceover (tmpfiles.org)').all();
const first = $('Split Scenes').first().json;

const dl = (u) => u.replace('tmpfiles.org/', 'tmpfiles.org/dl/');

return [{
  json: {
    meta: first.meta,
    outro_prompt: first.outro_prompt,
    scenes: scenes.map((s, i) => ({
      scene_index: s.scene_index,
      hook: s.hook,
      captions: s.captions,
      clip_url: dl(clips[i].json.data.url),
      audio_url: dl(voiceovers[i].json.data.url),
    })),
  },
}];

const parts = $input.first().json.candidates[0].content.parts;
const img = parts.find((p) => p.inlineData && (p.inlineData.mimeType || '').startsWith('image/'));
if (!img) {
  throw new Error('Nano Banana Pro ne image nahi bheji — prompt simplify karke dobara run karo');
}
return [{
  json: {},
  binary: {
    data: {
      data: img.inlineData.data,
      mimeType: img.inlineData.mimeType,
      fileName: 'outro.png',
    },
  },
}];

// Final movie JSON: Veo footage + Google TTS voiceover + hook + karaoke captions + branded outro
const assets = $('Assets Ready').first().json;
const cfg = $('1. Config and API Keys').first().json;
const outroUrl = $input.first().json.data.url.replace('tmpfiles.org/', 'tmpfiles.org/dl/');

const scenes = assets.scenes.map((s, i) => {
  const elements = [
    // Veo clip (mute — voiceover upar baithega)
    { type: 'video', src: s.clip_url, volume: 0 },
    // Gemini Pro TTS voiceover
    { type: 'audio', src: s.audio_url },
    // Golden hook caption (upar)
    { type: 'text', text: s.hook, position: 'top-center', 'font-size': 64, color: '#FFD700' },
  ];
  // Word-by-word karaoke captions (neeche, staggered)
  (s.captions || []).slice(0, 3).forEach((line, c) => {
    elements.push({
      type: 'text',
      text: line,
      position: 'bottom-center',
      'font-size': 72,
      color: '#FFFFFF',
      start: 0.4 + c * 2.6,
      duration: 2.6,
    });
  });
  const scene = { comment: 'Scene ' + (i + 1), duration: 8, elements };
  if (i > 0) scene.transition = { style: 'fade', duration: 0.5 };
  return scene;
});

// Branded outro (Nano Banana Pro image + follow CTA)
scenes.push({
  comment: 'Outro',
  duration: 3,
  elements: [
    { type: 'image', src: outroUrl, duration: 3 },
    { type: 'text', text: 'FOLLOW ' + (cfg.CHANNEL_TAG || ''), position: 'center', 'font-size': 84, color: '#FFFFFF' },
  ],
  transition: { style: 'fade', duration: 0.5 },
});

const movie = {
  comment: 'Professional AI Short — Gemini Pro + Veo + Nano Banana Pro',
  resolution: 'instagram-story',
  quality: 'high',
  scenes,
};

return [{ json: { movie, meta: assets.meta } }];
